from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    total_product = 1
    for number in numbers:
        total_product *= number
    return (total_sum, total_product) if numbers else (0, 1)

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def monotonic(l: list):
    if len(l) <= 1:
        return True
    increasing = decreasing = True
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            decreasing = False
        elif l[i] < l[i - 1]:
            increasing = False
    return increasing or decreasing

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest_factor = 1
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest_factor = 2
        n //= 2
    # n must be odd at this point, check for odd factors
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest_factor = n
    return largest_factor

def vowels_count(s):
    vowels = 'aeiouAEIOU'
    count = sum(1 for char in s if char in vowels)  # Count standard vowels
    if s and s[-1] in 'yY':
        count += 1  # Count 'y' if it's the last character
    if len(s) > 1 and s[-2] in 'yY' and s[-1] not in 'aeiouAEIOU':
        count += 1  # Count 'y' if it's the second to last character
    return count

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)
    if total_chars_lst1 <= total_chars_lst2:
        return lst1
    return lst2

