def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)

def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_sorted = sorted(set(lst))
    return unique_sorted[1] if len(unique_sorted) > 1 else None

def minPath(grid, k):
    n = len(grid)
    min_value = 1
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    result = []

    # Find the position of value '1'
    for i in range(n):
        for j in range(n):
            if grid[i][j] == min_value:
                start_x, start_y = i, j

    # Build the path of length k
    for step in range(k):
        result.append(min_value)
        neighbors = []
        # Explore neighbors to find the next minimum
e        for dx, dy in directions:
            nx, ny = start_x + dx, start_y + dy
            if 0 <= nx < n and 0 <= ny < n:
                neighbors.append(grid[nx][ny])

        if neighbors:
            min_neighbor = min(neighbors)
            result.append(min_neighbor)
            # Update current position
            if min_neighbor != min_value:
                for dx, dy in directions:
                    if grid[start_x + dx][start_y + dy] == min_neighbor:
                        start_x += dx
                        start_y += dy

    return result[:k]

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        elif i % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    return x if is_prime(n) else y

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
